SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "贺瑰围攻德胜南城并以艨艟阻晋援军。", "citation": "卷270·贞明五年（919）·zztj-v270-y0919-p009·原文件第82行", "note": "原文：贺瑰攻德胜南城，百道俱进，以竹笮联艨艟十馀艘，蒙以牛革，设睥睨、战格如城状，横于河流，以断晋之救兵，使不得渡。；核对说明：艨艟与竹笮设施按原文记录；本段另有两处私用字待校，事件标题不使用疑字。", "status": "draft", "id": "cdd338ac-a7f2-5863-96bf-e664dd4efd27", "subject_id": "b0206e35-5520-53cb-af36-4324a1883ff7", "source_id": "4dcad8c4-eb8a-5b50-a7e0-f5d4869ab812"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "919年四月前后本段；主书确日未载", "citation": "卷270·贞明五年（919）·zztj-v270-y0919-p009·原文件第82行", "note": "原文：贺瑰攻德胜南城，百道俱进，以竹笮联艨艟十馀艘，蒙以牛革，设睥睨、战格如城状，横于河流，以断晋之救兵，使不得渡。；核对说明：按主书本段纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "28bcc0cc-b9d3-53d1-baf8-f9facb7cd12b", "subject_id": "b0206e35-5520-53cb-af36-4324a1883ff7", "source_id": "4dcad8c4-eb8a-5b50-a7e0-f5d4869ab812"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记贺瑰：率梁军围攻并阻断河渡者。", "citation": "卷270·贞明五年（919）·zztj-v270-y0919-p009·原文件第82行", "note": "原文：贺瑰攻德胜南城，百道俱进，以竹笮联艨艟十馀艘，蒙以牛革，设睥睨、战格如城状，横于河流，以断晋之救兵，使不得渡。；核对说明：与既有规范名合并；繁简或异体仅用于实体匹配，引用保留原字。", "status": "draft", "id": "265070e2-7263-50a8-807a-41becee82e5d", "subject_id": "767516dc-02aa-5314-8b4b-b5be06aaa9bd", "source_id": "4dcad8c4-eb8a-5b50-a7e0-f5d4869ab812"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "贺瑰：率梁军围攻并阻断河渡者。", "citation": "卷270·贞明五年（919）·zztj-v270-y0919-p009·原文件第82行", "note": "原文：贺瑰攻德胜南城，百道俱进，以竹笮联艨艟十馀艘，蒙以牛革，设睥睨、战格如城状，横于河流，以断晋之救兵，使不得渡。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "d7853538-21cf-56c2-aec8-015f197cc39f", "subject_id": "026f4874-2683-5cea-abc4-ac578ddaca7a", "source_id": "4dcad8c4-eb8a-5b50-a7e0-f5d4869ab812"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》卷九记四月贺瑰攻德胜南城，以艨艟横河阻晋援军。", "citation": "《旧五代史》卷九，段落 jiu-wudaishi-205deb4a7860-p000424；EPUB电子本，纸本及异文待核", "note": "原文：是月，賀瑰攻德勝南城，以艨艟戰艦橫於河，以扼津濟之路。；核对说明：旧书记四月，与主书本段未标确日的叙事相接；补书未记李建及等具体破障经过。", "status": "draft", "id": "50d80b5f-9c0b-5cb3-8e53-8277c53a0f6f", "subject_id": "b0206e35-5520-53cb-af36-4324a1883ff7", "source_id": "a5b6e8e2-ee66-57ec-8b20-9d43824bd229"}, {"subject_table": "event", "field_path": "description", "claim_text": "晋王驰援德胜并遣马破龙入城探报。", "citation": "卷270·贞明五年（919）·zztj-v270-y0919-p009·原文件第82行", "note": "原文：晋王自引兵驰往救之，陈于北岸，不能进；遣善游者马破龙入南城，见守将氏延赏，延赏言矢石将尽，陷在顷刻。；核对说明：晋军初被截河不得渡；氏延赏报告矢石将尽，不把预期失守写作实际失守。", "status": "draft", "id": "18523890-9c81-5458-a77b-007570200f13", "subject_id": "60b67356-ad59-59b9-9885-eb81713a2c29", "source_id": "4dcad8c4-eb8a-5b50-a7e0-f5d4869ab812"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "919年德胜南城围攻期间；确日未载", "citation": "卷270·贞明五年（919）·zztj-v270-y0919-p009·原文件第82行", "note": "原文：晋王自引兵驰往救之，陈于北岸，不能进；遣善游者马破龙入南城，见守将氏延赏，延赏言矢石将尽，陷在顷刻。；核对说明：按主书本段纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "c976f6f3-f93f-520a-8d51-93359c88aa55", "subject_id": "60b67356-ad59-59b9-9885-eb81713a2c29", "source_id": "4dcad8c4-eb8a-5b50-a7e0-f5d4869ab812"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记李存勖：率兵驰援并遣人探城者。", "citation": "卷270·贞明五年（919）·zztj-v270-y0919-p009·原文件第82行", "note": "原文：晋王自引兵驰往救之，陈于北岸，不能进；遣善游者马破龙入南城，见守将氏延赏，延赏言矢石将尽，陷在顷刻。；核对说明：与既有规范名合并；繁简或异体仅用于实体匹配，引用保留原字。", "status": "draft", "id": "efc9e7f7-1561-561f-bb47-b4cfb7728368", "subject_id": "4e068da9-c8dd-5a31-a747-87669e3bf993", "source_id": "4dcad8c4-eb8a-5b50-a7e0-f5d4869ab812"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "晋王：率兵驰援并遣人探城者。", "citation": "卷270·贞明五年（919）·zztj-v270-y0919-p009·原文件第82行", "note": "原文：晋王自引兵驰往救之，陈于北岸，不能进；遣善游者马破龙入南城，见守将氏延赏，延赏言矢石将尽，陷在顷刻。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "6d278580-bb25-5e95-b718-da029b0c7589", "subject_id": "abeb8bbd-b5cd-5f74-bccd-4ef98d00d73f", "source_id": "4dcad8c4-eb8a-5b50-a7e0-f5d4869ab812"}, {"